cd build && python -c "
import numpy as np
names=['V1','V2','V3','V4','V5','V6','V7','V8','V9','V10','V11','Vf','Vg','Vh','Mef','Me8','Ci','Mea','Meb','O1','O2','O5','O4','O2h','O1h','Ogh','O7']
L=[l.split() for l in open('opt.xyz').read().split('\n')[2:] if l.strip()]
X=np.array([[float(v) for v in l[1:4]] for l in L]); el=[l[0] for l in L]
idx={n:i for i,n in enumerate(names)}
ring=[idx[n] for n in ['V6','V7','V9','V10','V8','V11']]
c=X[ring].mean(0); u,s,vt=np.linalg.svd(X[ring]-c); nrm=vt[2]
def ang(a,b): v=X[idx[b]]-X[idx[a]]; return np.degrees(np.arccos(abs(v@nrm)/np.linalg.norm(v)))
for a,b in [('V7','O7'),('V7','Vf'),('V11','O1'),('V8','Me8'),('V6','O2'),('V6','V5')]: print(a,b,'angle to ring normal %.0f'%ang(a,b))
# H on V11 and V8
for a in ['V11','V8']:
    for j,e in enumerate(el):
        if e=='H' and np.linalg.norm(X[j]-X[idx[a]])<1.2: print(a,'H',j,'angle to normal %.0f'%np.degrees(np.arccos(abs((X[j]-X[idx[a]])@nrm)/np.linalg.norm(X[j]-X[idx[a]]))))
"
